---
import type { ImageMetadata } from "astro"
import type { HTMLAttributes } from "astro/types"

import { cn } from "@/lib/utils"
import {
  Avatar,
  AvatarFallback,
  AvatarGroup,
  AvatarImage,
} from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Rating } from "@/components/ui/rating"
import {
  Section,
  SectionContainer,
  SectionDescription,
  SectionTitle,
} from "@/components/ui/section"

type Props = HTMLAttributes<"section"> & {
  title: string
  description: string
  buttons: {
    label: string
    href: string
  }[]
  socialProof?: {
    avatars: {
      image?: ImageMetadata
      initials: string
    }[]
    rating: number
    ratingLabel: string
    text: string
  }
}

const {
  class: className,
  title,
  description,
  buttons,
  socialProof,
  ...props
} = Astro.props
---

<Section variant="floating" class={cn("", className)} {...props}>
  <SectionContainer class="flex flex-col gap-8 items-center text-center">
    {socialProof && (
      <div class="flex flex-col items-center gap-3">
        <AvatarGroup aria-hidden="true">
          {socialProof.avatars.map((avatar) => (
            <Avatar class="ring-background size-11 ring">
              <AvatarImage src={avatar.image} />
              <AvatarFallback>{avatar.initials}</AvatarFallback>
            </Avatar>
          ))}
        </AvatarGroup>
        <div class="flex items-center gap-2">
          <Rating
            value={socialProof.rating}
            aria-label={socialProof.ratingLabel}
          />
          <span class="text-muted-foreground text-sm">{socialProof.text}</span>
        </div>
      </div>
    )}
    <div class="flex max-w-2xl flex-col items-center gap-5">
      <SectionTitle class="leading-[1.1]">{title}</SectionTitle>
      <SectionDescription>{description}</SectionDescription>
    </div>
    <div class="flex flex-wrap justify-center gap-3">
      {buttons.map(({ href, label }, index) => (
        <Button
          as="a"
          href={href}
          size="lg"
          variant={index === 0 ? "default" : "secondary"}
        >
          {label}
        </Button>
      ))}
    </div>
  </SectionContainer>
</Section>
